  // Try to find chart instance
  let chartInstance = null;
  for (const key in canvas) {
    if (key.startsWith('__chartjs') || key.startsWith('chart')) {
      chartInstance = canvas[key];
    }
  }

  // Check Chart.instances
  if (!chartInstance && window.Chart && window.Chart.instances) {
    const ids = Object.keys(window.Chart.instances);
    if (ids.length > 0) chartInstance = window.Chart.instances[ids[0]];
  }

  if (chartInstance && chartInstance.data) {
    return {
      labels: chartInstance.data.labels,
      datasets: chartInstance.data.datasets?.map(ds => ({
        label: ds.label,
        data: ds.data
      }))
    };
  }

  return { error: "No chart instance found directly on canvas" };
});

